<?php if (session_status() === PHP_SESSION_NONE) { session_start(); } require_once __DIR__ . '/database.php'; /* * Проверяет, авторизован ли пользователь. */ function isLoggedIn() { return isset($_SESSION['user_id']); } /* * Возвращает ID текущего пользователя. */ function currentUserId() { if (!isset($_SESSION['user_id'])) { return null; } return (int) $_SESSION['user_id']; } /* * Получает текущего пользователя из базы. */ function currentUser() { global $pdo; $userId = currentUserId(); if ($userId === null) { return null; } $stmt = $pdo->prepare( 'SELECT id, username, city_id, category_id, role, is_blocked, last_activity FROM users WHERE id = ? LIMIT 1' ); $stmt->execute(array($userId)); $user = $stmt->fetch(); if (!$user) { return null; } return $user; } /* * Требует авторизации. */ function requireLogin() { if (!isLoggedIn()) { header('Location: login.php'); exit; } } /* * Требует права администратора. */ function requireAdmin() { requireLogin(); $user = currentUser(); if (!$user || $user['role'] !== 'admin') { http_response_code(403); exit('Доступ запрещён.'); } } /* * Обновляет время последней активности. */ function updateLastActivity() { global $pdo; $userId = currentUserId(); if ($userId === null) { return; } $stmt = $pdo->prepare( 'UPDATE users SET last_activity = NOW() WHERE id = ?' ); $stmt->execute(array($userId)); } /* * Проверяет блокировку пользователя. */ function checkBlocked() { $user = currentUser(); if ($user && (int) $user['is_blocked'] === 1) { session_destroy(); http_response_code(403); exit('Ваш аккаунт заблокирован.'); } } /* * Проверяет, есть ли у текущего пользователя * указанное разрешение. * * Администратор имеет все разрешения. */ function can($permission) { global $pdo; $user = currentUser(); if (!$user) { return false; } /* * Администратор имеет полный доступ. */ if ($user['role'] === 'admin') { return true; } /* * Получаем разрешение для роли пользователя. */ $stmt = $pdo->prepare( 'SELECT rp.permission_id FROM role_permissions rp INNER JOIN permissions p ON p.id = rp.permission_id WHERE rp.role = ? AND p.name = ? LIMIT 1' ); $stmt->execute(array( $user['role'], $permission )); return (bool) $stmt->fetch(); } /* * Проверяет, ограничил ли текущий пользователь * другого пользователя. * * $type: * chat — запрет общения * profile — запрет доступа к профилю */ function hasRestriction($targetUserId, $type) { global $pdo; $userId = currentUserId(); if ($userId === null) { return false; } $targetUserId = (int) $targetUserId; if ($targetUserId <= 0 || $targetUserId === $userId) { return false; } $stmt = $pdo->prepare( 'SELECT id FROM user_restrictions WHERE user_id = ? AND target_user_id = ? AND restriction_type = ? LIMIT 1' ); $stmt->execute(array( $userId, $targetUserId, $type )); return (bool) $stmt->fetch(); } /* * Проверяет, запретил ли другой пользователь * доступ текущему пользователю. */ function isRestrictedByUser($targetUserId, $type) { global $pdo; $userId = currentUserId(); if ($userId === null) { return false; } $targetUserId = (int) $targetUserId; if ($targetUserId <= 0 || $targetUserId === $userId) { return false; } $stmt = $pdo->prepare( 'SELECT id FROM user_restrictions WHERE user_id = ? AND target_user_id = ? AND restriction_type = ? LIMIT 1' ); $stmt->execute(array( $targetUserId, $userId, $type )); return (bool) $stmt->fetch(); } /* * Проверяет наличие ограничения * в любую сторону. */ function hasAnyRestriction($userA, $userB, $type) { return ( hasRestriction($userB, $type) || isRestrictedByUser($userB, $type) ); } /* * Возвращает CSRF-токен текущей сессии. * * Совместимо с PHP 5.6. */ function csrfToken() { if ( !isset($_SESSION['csrf_token']) || !is_string($_SESSION['csrf_token']) || strlen($_SESSION['csrf_token']) < 32 ) { if (function_exists('openssl_random_pseudo_bytes')) { $_SESSION['csrf_token'] = bin2hex( openssl_random_pseudo_bytes(32) ); } else { $_SESSION['csrf_token'] = hash( 'sha256', uniqid(mt_rand(), true) ); } } return $_SESSION['csrf_token']; } /* * Проверяет CSRF-токен. */ function verifyCsrfToken($token) { if ( !isset($_SESSION['csrf_token']) || !is_string($token) ) { return false; } if (function_exists('hash_equals')) { return hash_equals( $_SESSION['csrf_token'], $token ); } return $_SESSION['csrf_token'] === $token; } ?>